<?php
// Group use statements regenerated by the translation (CRLF, comments, close tag) and translated again.
namespace Lib {
    function other() { return 'Lib\other'; }
    const K = 'Lib\K';
}
namespace {
    use phasync\Babel\Babel;

    $b = new Babel(['Lib\fopen' => 'Hook\fopen_alt', 'Lib\read' => 'Hook\fopen', 'fopen' => 'Hook\fopen']);
    $srcs = [
        "namespace App;\r\nuse Lib\\{function fopen, /* c */ function read as r,\r\n Thing, const K};\r\nuse function Lib\\{fopen as fo2, other};\r\necho fopen('x'), r(1), fo2(), other(), K, \"\\n\";\r\n",
        "namespace App2;\nuse function Lib\\{\n  fopen, // first\n  other\n} ?>\n<?php echo fopen('y'), other(), \"\\n\";\n",
        "namespace App3 { use function Lib\\{read as fopen}; use function Lib\\fopen as read; echo fopen(1), read(2), \"\\n\"; }",
    ];
    foreach ($srcs as $n => $src) {
        $t1 = $b->translate($src, "/virtual/x.php(1) : eval()'d code");
        $bare = str_replace($b->marker, '', $t1);
        $t2 = str_replace($b->marker, '', $b->translate($bare, "/virtual/y.php(2) : eval()'d code"));
        echo $n, ': ', $t2 === $bare ? 'same' : "CHANGED\n$bare\n$t2\n", ' ', substr_count($src, "\n") === substr_count($t1, "\n") ? 'lines' : 'LINES', "\n";
        eval($t1);
        eval($bare);
    }
}
